function [r, phi, lam] = body_angles(rb)
%BODY_ANGLES  A body's distance, latitude and longitude as the MATLAB forms them (norm, asin, atan2).
%   rb: real[1][3] (passed a plain number)
%   returns r: real[1] (passed a plain number)
%   returns phi: real[1] (passed a plain number)
%   returns lam: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = 0;
    phi = 0;
    lam = 0;
    r = asils.models.gravity.onorm(rb);
    phi = asin((rb(3) / r));
    lam = atan2(rb(2), rb(1));
end
